ENTERPRISE_UI_EXTENSION = r"""
<style>
.enterprise-layer-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.enterprise-layer{border:1px solid #c7c7c7;padding:12px;min-height:150px}.enterprise-layer strong{display:block;font-size:16px;margin:7px 0}.enterprise-list{max-height:220px;overflow:auto;margin-top:8px}.enterprise-row{padding:7px 0;border-bottom:1px solid #ddd;font:10px/1.45 Consolas,monospace}.enterprise-row:last-child{border-bottom:0}.command-grid{display:grid;grid-template-columns:1.15fr .85fr;gap:14px}.command-card{border:1px solid #c7c7c7;padding:13px;min-width:0}.command-hero{display:grid;grid-template-columns:repeat(5,1fr);border-left:1px solid #c7c7c7;border-top:1px solid #c7c7c7;margin:12px 0}.command-hero>div{padding:11px;border-right:1px solid #c7c7c7;border-bottom:1px solid #c7c7c7}.command-hero strong{display:block;font-size:18px;margin-top:4px}.command-output{white-space:pre-wrap;word-break:break-word;font:10px/1.45 Consolas,monospace;max-height:380px;overflow:auto}.command-timeline{max-height:420px;overflow:auto}.command-time{border-left:2px solid #111;padding:5px 0 8px 10px;margin-bottom:7px}.command-time b{display:block;font-size:10px}.command-time span{font-size:9px;color:#555}.command-actions{display:flex;gap:7px;flex-wrap:wrap;margin-top:10px}.command-danger{border:2px solid #111}.command-status{font:10px/1.45 Consolas,monospace;margin-top:8px;min-height:15px}@media(max-width:1000px){.enterprise-layer-grid,.command-grid{grid-template-columns:1fr}.command-hero{grid-template-columns:1fr 1fr}}
</style>
<script>
(()=>{
const E=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function adminToken(){return sessionStorage.getItem('campusOpsAdminToken')||''}
function headers(){const t=adminToken();return t?{'X-Campus-Admin':t}:{}}
async function get(path,admin=false){const r=await fetch(path,{cache:'no-store',headers:admin?headers():{}}),d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.detail||`HTTP ${r.status}`);return d}
async function post(path,body){const r=await fetch(path,{method:'POST',headers:{...headers(),'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)}),d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.detail||`HTTP ${r.status}`);return d}
function injectTopologyLayers(){const view=E('view-topology');if(!view||E('enterpriseTopologyLayers'))return;const s=document.createElement('section');s.id='enterpriseTopologyLayers';s.innerHTML='<div class="sectionhead"><div><h2>Topology Layers</h2><div class="small">Physical evidence, logical segmentation and application visibility are kept separate.</div></div><button class="btn" id="enterpriseTopologyRefresh">Refresh Layers</button></div><div class="enterprise-layer-grid"><div class="enterprise-layer"><div class="label">Physical Infrastructure</div><strong id="physicalLayerState">—</strong><div class="small">LLDP / CDP / SNMP evidence only.</div><div class="enterprise-list" id="physicalLayerList"></div></div><div class="enterprise-layer"><div class="label">Logical Segmentation</div><strong id="logicalLayerState">—</strong><div class="small">Observed prefixes and explicit policy.</div><div class="enterprise-list" id="logicalLayerList"></div></div><div class="enterprise-layer"><div class="label">Application Layer</div><strong id="applicationLayerState">—</strong><div class="small">DNS, TLS SNI and HTTP host evidence.</div><div class="enterprise-list" id="applicationLayerList"></div></div></div>';view.appendChild(s);E('enterpriseTopologyRefresh').onclick=loadTopologyLayers;loadTopologyLayers()}
async function loadTopologyLayers(){try{const d=await get('/api/v1/system/network-depth'),policy=await get('/api/v1/system/segmentation-policy'),p=d.physical_topology||{},l=d.segmentation||{},a=d.dns_tls||{};E('physicalLayerState').textContent=p.state||'UNKNOWN';E('physicalLayerList').innerHTML=(p.links||[]).slice(0,20).map(x=>`<div class="enterprise-row">${esc(x.local||'?')} ${esc(x.local_port||'')} → ${esc(x.remote||'?')} ${esc(x.remote_port||'')}</div>`).join('')||'<div class="muted">No physical topology evidence.</div>';E('logicalLayerState').textContent=policy.state==='ACTIVE'?`${policy.violation_count||0} POLICY VIOLATIONS`:(l.vlan_state||policy.state||'UNKNOWN');E('logicalLayerList').innerHTML=(l.flow_classes||[]).slice(0,20).map(x=>`<div class="enterprise-row">${esc(x.class)} · ${Number(x.flows||0)} flows</div>`).join('')||'<div class="muted">No logical flow classes.</div>';const appRows=[...(a.dns||[]).slice(0,8),...(a.tls_sni||[]).slice(0,8)];E('applicationLayerState').textContent=a.state||'UNKNOWN';E('applicationLayerList').innerHTML=appRows.map(x=>`<div class="enterprise-row">${esc(x.name)} · ${Number(x.observations||0)}</div>`).join('')||'<div class="muted">No application evidence.</div>'}catch(e){if(E('physicalLayerState'))E('physicalLayerState').textContent='UNAVAILABLE'}}
function injectCommandCenter(){if(!adminToken()||E('view-admin-command'))return;const nav=document.querySelector('nav'),main=document.querySelector('main'),foot=main?.querySelector('.foot');if(!nav||!main||typeof pages==='undefined')return;pages['admin-command']=['Command Center','Unified target investigation and response workspace.'];const b=document.createElement('button');b.className='tab admin-tab show';b.dataset.view='admin-command';b.textContent='Command Center';b.onclick=()=>setView('admin-command');nav.appendChild(b);const view=document.createElement('div');view.className='view';view.id='view-admin-command';view.innerHTML='<section class="admin-shell"><div class="sectionhead"><div><h2>Admin Command Center</h2><div class="small">One target. Network, endpoint, identity, evidence and response in one workspace.</div></div></div><div class="admin-targetbar"><input id="commandTarget" placeholder="Target IP / endpoint ID"><button class="btn" id="commandRun">Build Dossier</button><button class="btn" id="commandManifest">Evidence Manifest</button></div><div class="command-hero" id="commandHero"></div><div class="command-grid"><div class="command-card"><div class="label">Attack Story</div><div class="command-timeline" id="commandTimeline"></div></div><div class="command-card"><div class="label">Decision Support</div><div id="commandDecision"></div><div class="label" style="margin-top:14px">Network Peers</div><div id="commandPeers"></div></div></div><div class="command-grid" style="margin-top:14px"><div class="command-card"><div class="label">Process / Endpoint Evidence</div><div id="commandProcesses"></div></div><div class="command-card"><div class="label">DNS / TLS Anomalies</div><div id="commandAnomalies"></div></div></div><div class="command-grid" style="margin-top:14px"><div class="command-card"><div class="label">Identity Context</div><div id="commandIdentity">No identity query yet.</div></div><div class="command-card"><div class="label">SOAR / Response</div><div id="commandSoar">Build a target dossier first.</div><div class="command-actions"><button class="btn" id="commandTriage">Queue Triage Snapshot</button><button class="btn command-danger" id="commandContain">Queue Snapshot + Isolation</button></div><div class="command-status" id="commandSoarStatus"></div></div></div><div class="command-card" style="margin-top:14px"><div class="label">Evidence</div><div class="command-actions"><button class="btn" id="commandExport">Export Evidence Bundle</button></div><div class="command-status" id="commandExportStatus"></div><pre class="command-output" id="commandManifestOut">Build a target dossier first.</pre></div></section>';main.insertBefore(view,foot||null);E('commandRun').onclick=runCommandCenter;E('commandManifest').onclick=loadManifest;E('commandTriage').onclick=()=>executeSoar('TRIAGE');E('commandContain').onclick=()=>executeSoar('CONTAIN');E('commandExport').onclick=exportEvidence}
async function runCommandCenter(){const t=(E('commandTarget')?.value||'').trim();if(!t)return;E('commandHero').innerHTML='<div><div class="label">State</div><strong>LOADING</strong></div>';try{const [d,identity,soar]=await Promise.all([get('/api/v1/admin/command-center/'+encodeURIComponent(t),true),get('/api/v1/admin/identity/'+encodeURIComponent(t),true),get('/api/v1/admin/soar/'+encodeURIComponent(t)+'?playbook=TRIAGE',true)]),story=d.attack_story||{},network=d.network||{},policy=d.segmentation_policy||{};E('commandHero').innerHTML=[['Target',t],['Risk',d.risk??0],['Confidence',(d.confidence??0)+'%'],['Evidence',story.evidence_sources?.length||0],['Containment',d.containment_ready?'READY':'NO MANAGED AGENT']].map(x=>`<div><div class="label">${esc(x[0])}</div><strong>${esc(x[1])}</strong></div>`).join('');E('commandTimeline').innerHTML=(story.timeline||[]).slice(0,80).map(x=>`<div class="command-time"><b>${esc(x.severity||'INFO')} · ${esc(x.title||x.type||'event')}</b><span>${esc(x.time||'')} · ${esc(x.source||'')} · ${esc(x.evidence_class||'')}</span></div>`).join('')||'<div class="muted">No current-session attack story.</div>';E('commandDecision').innerHTML=`<div class="admin-row"><b>Truth:</b> ${esc(d.truth_state||'UNKNOWN')}</div><div class="admin-row"><b>Policy:</b> ${esc(policy.state||'NOT CONFIGURED')} · ${Number(policy.violation_count||0)} violations</div><div class="admin-row"><b>Sigma:</b> ${esc((d.sigma||{}).state||'UNKNOWN')}</div><div class="admin-row"><b>Response:</b> ${d.containment_ready?'managed endpoint available':'passive evidence only'}</div>`;E('commandPeers').innerHTML=(network.top_peers||[]).slice(0,25).map(x=>`<div class="enterprise-row">${esc(x.peer)} · ${Number(x.flows||0)} flows</div>`).join('')||'<div class="muted">No peers observed.</div>';E('commandProcesses').innerHTML=(d.host_process_matches||[]).slice(0,25).map(x=>`<div class="enterprise-row">PID ${esc(x.pid)} · ${esc(x.name||'process')} · ${esc(x.user||'')} · ${Number(x.connection_count||0)} connections</div>`).join('')||'<div class="muted">No process mapping for this target.</div>';E('commandAnomalies').innerHTML=((d.dns_tls_anomalies||{}).findings||[]).slice(0,30).map(x=>`<div class="enterprise-row">${esc(x.type)} · score ${esc(x.score)} · ${esc(x.value)} · ${esc((x.reasons||[]).join(', '))}</div>`).join('')||'<div class="muted">No current DNS/TLS anomaly findings.</div>';E('commandIdentity').innerHTML=(identity.matches||[]).map(x=>`<div class="enterprise-row">${esc(x.username||'unknown user')} · ${esc(x.ip||'no IP')} · ${esc(x.mac||'no MAC')} · VLAN ${esc(x.vlan||'unknown')} · ${esc(x.switch_port||'port unknown')}</div>`).join('')||'<div class="muted">No NAC/RADIUS/802.1X identity evidence.</div>';E('commandSoar').innerHTML=`<div class="admin-row"><b>Executable:</b> ${soar.executable?'YES':'NO MANAGED AGENT'}</div><div class="admin-row"><b>Guardrails:</b> ${esc((soar.guardrails||[]).join(' · '))}</div>`;E('commandManifestOut').textContent=JSON.stringify(d.evidence_manifest||{},null,2)}catch(e){E('commandHero').innerHTML=`<div><div class="label">Error</div><strong>${esc(e.message)}</strong></div>`}}
async function loadManifest(){const t=(E('commandTarget')?.value||'').trim();if(!t)return;try{const d=await get('/api/v1/admin/evidence-manifest/'+encodeURIComponent(t),true);E('commandManifestOut').textContent=JSON.stringify(d,null,2)}catch(e){E('commandManifestOut').textContent=e.message}}
async function executeSoar(playbook){const t=(E('commandTarget')?.value||'').trim();if(!t)return;const disruptive=playbook==='CONTAIN';if(disruptive&&!window.confirm(`Contain ${t}? This queues a snapshot and host isolation on the managed endpoint.`))return;if(!disruptive&&!window.confirm(`Queue a forensic snapshot for ${t}?`))return;E('commandSoarStatus').textContent='Queuing response...';try{const d=await post('/api/v1/admin/soar/'+encodeURIComponent(t)+'/execute',{playbook,confirm:true,reason:'admin command center'});E('commandSoarStatus').textContent=`${d.queued_jobs?.length||0} job(s) queued. Restore was not queued.`}catch(e){E('commandSoarStatus').textContent=e.message}}
async function exportEvidence(){const t=(E('commandTarget')?.value||'').trim();if(!t)return;E('commandExportStatus').textContent='Exporting evidence bundle...';try{const d=await post('/api/v1/admin/evidence-export/'+encodeURIComponent(t));E('commandExportStatus').textContent=`Saved ${d.bytes||0} bytes · SHA256 ${d.sha256||'—'} · ${d.path||''}`;}catch(e){E('commandExportStatus').textContent=e.message}}
function tick(){injectTopologyLayers();injectCommandCenter()}tick();setInterval(tick,1500);
})();
</script>
"""